#!/usr/bin/env node
/**
 * Regenerate the bundled icon modules from the pinned OpenAI Apps SDK UI
 * source. The generated files are committed (they are build inputs), but the
 * pinned upstream is the single source of truth — never hand-edit path data.
 *
 * Usage:
 *   node scripts/generate-icon-data.mjs --source <apps-sdk-ui>/src/components/Icon/svg
 *
 * Produces:
 *   src/client/icons/icon-data.ts        curated 62 glyphs, inlined in the client bundle
 *   src/client/icons/icon-data-full.ts   all glyphs, lazy asset only
 *   src/client/icons/icon-names-full.ts  name list, inlined so a typo never downloads
 *
 * Upstream: https://github.com/openai/apps-sdk-ui @ 0f00143c7a639906f1621fe58e1b6be7b5bea46d (MIT).
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { parseArgs } from 'node:util'

const { values } = parseArgs({
  options: {
    source: { type: 'string' },
    out: { type: 'string', default: 'src/client/icons' },
  },
  strict: true,
})

if (values.source === undefined) {
  console.error('usage: node scripts/generate-icon-data.mjs --source <apps-sdk-ui>/src/components/Icon/svg')
  process.exit(1)
}

/** The inlined set: states, arrows and the compute primitives figures are built from. */
const INLINE = [
  'Check', 'CheckCircle', 'Info', 'InfoCircle', 'Warning', 'Error', 'X', 'Plus', 'Minus', 'Circle',
  'ArrowDown', 'ArrowUp', 'ArrowRight', 'ArrowLeft', 'ArrowCurvedRight',
  'Function', 'Functions', 'Operator', 'Atom', 'Nodes', 'Connect', 'Share', 'Branch', 'Grid', 'GridAlt', 'Stack',
  'Cube', 'Storage', 'Chart', 'Trending', 'Pulse', 'Speed', 'Timer', 'Clock', 'TableFilled',
  'Code', 'SquareCode', 'Terminal', 'File', 'FileCode', 'Folder', 'Link', 'Paperclip',
  'Lightbulb', 'Book', 'BookOpen', 'GraduationCap', 'Flask', 'Lab', 'Brain', 'Robot', 'Sparkles',
  'ShieldCheck', 'Lock', 'Globe', 'WebsiteNetwork', 'Search', 'MagnifyingGlassSearch',
  'PluginPuzzle', 'Settings', 'Bolt', 'Compass',
]

const HEADER = `/**
 * OpenAI Apps SDK UI icons — https://github.com/openai/apps-sdk-ui
 * Pinned commit 0f00143c7a639906f1621fe58e1b6be7b5bea46d · MIT · Copyright 2025 OpenAI.
 * See THIRD_PARTY_NOTICES.md.
 *
 * Generated by scripts/generate-icon-data.mjs — do not hand-edit path data.
 */`

const catalogue = {}
for (const file of readdirSync(values.source)) {
  if (!/\.(tsx|ts|jsx|js)$/.test(file)) continue
  const source = readFileSync(join(values.source, file), 'utf8')
  const paths = [...source.matchAll(/"d"\s*:\s*"([^"]+)"|d="([^"]+)"/g)].map(m => m[1] ?? m[2])
  if (paths.length === 0) continue
  const viewBox = /viewBox[^0-9]*([0-9.\- ]+)/.exec(source)?.[1]?.trim() ?? '0 0 24 24'
  catalogue[file.replace(/\.(tsx|ts|jsx|js)$/, '')] = { viewBox, paths }
}

const names = Object.keys(catalogue).sort()
const body = (list) => list.map(name => {
  const { viewBox, paths } = catalogue[name]
  return `  ${name}: {\n    viewBox: '${viewBox}',\n    paths: [\n${paths.map(d => `      '${d}',`).join('\n')}\n    ],\n  },`
}).join('\n')

const bundled = (list, doc) => `${HEADER}\n/** ${doc} */\nimport type { BundledIcon } from './icon-data.ts'\n\nexport const ICONS${list === names ? '_FULL' : ''}: Readonly<Record<string, BundledIcon>> = {\n${body(list)}\n}\n`

writeFileSync(join(values.out, 'icon-data-full.ts'),
  bundled(names, `Full catalogue (${names.length} glyphs). Imported only by the lazy asset entry.`))

writeFileSync(join(values.out, 'icon-data.ts'),
  `${HEADER}\n/**\n * Curated inline set (${INLINE.length} glyphs): ships in the client bundle so the common\n * figure vocabulary renders without a download. Everything else lives in\n * icon-data-full.ts behind lib/assets/icons.js.\n */\nexport interface BundledIcon {\n  viewBox: string\n  /** One SVG path command per subpath, drawn with the current text colour. */\n  paths: string[]\n}\n\nexport const ICONS: Readonly<Record<string, BundledIcon>> = {\n${body(INLINE.filter(name => catalogue[name] !== undefined))}\n}\n`)

writeFileSync(join(values.out, 'icon-names-full.ts'),
  `${HEADER}\n/**\n * Every canonical name (${names.length}). Inlined as names only so the renderer can tell\n * a typo from "not downloaded yet" without fetching the glyph bundle.\n */\nexport const ICON_NAMES_FULL: readonly string[] = ${JSON.stringify(names)}\n`)

console.log(`icons: ${names.length} total, ${INLINE.filter(n => catalogue[n] !== undefined).length} inline -> ${values.out}`)
